"""The store: one directory, an ordered set of sealed tables, and one live write-ahead log.

Read path: memtable -> newest sealed table -> ... -> oldest. A tombstone found on the way *is* the
answer (the key is deleted); only a full miss means the key never existed.

Write path: WAL first (so a crash cannot lose an acknowledged write), then the memtable. `flush`
seals the memtable into a new table and resets the log; `compact` merges every table into one and
drops tombstones that no longer hide anything.
"""

from __future__ import annotations

import heapq
import os
import re
from bisect import bisect_left
from dataclasses import dataclass, field
from typing import Iterator

from .errors import ValidationError
from .memtable import MemTable
from .sstable import EMPTY_MARKER, TOMBSTONE_BYTE, SSTable, TableWriter
from .wal import DEL, PUT, WriteAheadLog, replay

TABLE_PATTERN = re.compile(r"^table-(\d+)\.sst$")


class _Cursor:
    """One ordered layer in the k-way merge. Lower rank wins a key tie (newer layer wins).

    The head is ``(key, marker_or_value)``: table cursors carry only the value-marker byte and
    fetch the value on demand, while the memtable cursor carries the value directly.
    """

    __slots__ = ("rank", "key", "payload")

    def __init__(self, rank: int) -> None:
        self.rank = rank
        self.key: str | None = None
        self.payload: object = None

    def __lt__(self, other: "_Cursor") -> bool:
        return (self.key, self.rank) < (other.key, other.rank)


class _MemTableCursor(_Cursor):
    __slots__ = ("entries", "positions", "index")

    def __init__(self, entries: dict[str, str | None], start: str | None) -> None:
        super().__init__(rank=0)  # the memtable is the newest layer
        self.entries = entries
        self.positions = sorted(entries)
        self.index = bisect_left(self.positions, start) if start is not None else 0
        self._load()

    def _load(self) -> None:
        if self.index < len(self.positions):
            self.key = self.positions[self.index]
            self.payload = self.entries[self.key]
        else:
            self.key = None

    @property
    def tombstone(self) -> bool:
        return self.payload is None

    def advance(self) -> None:
        self.index += 1
        self._load()

    def read_value(self) -> str:
        return self.payload  # type: ignore[return-value]


class _TableCursor(_Cursor):
    __slots__ = ("stream")

    def __init__(self, table: SSTable, rank: int, start: str | None) -> None:
        super().__init__(rank=rank)
        self.stream = table.open_stream(start)
        if self.stream.head is None:
            self.key = None
        else:
            self.key, self.payload = self.stream.head

    def advance(self) -> None:
        self.stream.advance()
        if self.stream.head is None:
            self.key = None
        else:
            self.key, self.payload = self.stream.head

    @property
    def tombstone(self) -> bool:
        return self.payload == TOMBSTONE_BYTE

    def read_value(self) -> str:
        if self.payload == EMPTY_MARKER:  # empty-string value: no value bytes to fetch
            return ""
        return self.stream.value()

    def close(self) -> None:
        self.stream.close()


@dataclass(frozen=True, slots=True)
class StoreStats:
    directory: str
    tables: int
    sealed_entries: int
    memtable_entries: int
    memtable_bytes: int
    tombstones: int
    wal_records: int
    wal_truncated_bytes: int
    next_table_number: int

    def to_document(self) -> dict[str, object]:
        return {
            "directory": self.directory,
            "tables": self.tables,
            "sealedEntries": self.sealed_entries,
            "memtableEntries": self.memtable_entries,
            "memtableBytes": self.memtable_bytes,
            "tombstones": self.tombstones,
            "walRecords": self.wal_records,
            "walTruncatedBytes": self.wal_truncated_bytes,
            "nextTableNumber": self.next_table_number,
        }


@dataclass(frozen=True, slots=True)
class Snapshot:
    """A point-in-time view: tombstones are already resolved away."""

    sequence: int
    visible: tuple[tuple[str, str], ...]

    def get(self, key: str, default: str | None = None) -> str | None:
        for candidate, value in self.visible:
            if candidate == key:
                return value
        return default

    def items(self) -> list[tuple[str, str]]:
        return list(self.visible)

    def to_document(self) -> dict[str, object]:
        return {"sequence": self.sequence, "keys": len(self.visible)}


@dataclass(slots=True)
class Store:
    directory: str
    memtable_limit_bytes: int = 1 << 20
    memtable: MemTable = field(init=False)
    tables: list[SSTable] = field(default_factory=list, init=False)
    wal: WriteAheadLog = field(init=False)
    wal_records: int = field(default=0, init=False)
    wal_truncated_bytes: int = field(default=0, init=False)
    writes: int = field(default=0, init=False)

    def __post_init__(self) -> None:
        if self.memtable_limit_bytes <= 0:
            raise ValidationError("memtable_limit_bytes must be > 0", value=self.memtable_limit_bytes)
        self.memtable = MemTable(limit_bytes=self.memtable_limit_bytes)
        self.wal = WriteAheadLog(os.path.join(self.directory, "wal.log"))

    # -- lifecycle -----------------------------------------------------------
    def open(self) -> "Store":
        os.makedirs(self.directory, exist_ok=True)
        self.tables = [SSTable.open(path) for path in self._table_paths()]
        self.tables.reverse()  # newest first
        self.wal.open()
        report = self.wal.recover()
        self.wal_records = len(report.records)
        self.wal_truncated_bytes = report.truncated_bytes
        for payload in report.records:
            if payload["op"] == PUT:
                self.memtable.put(str(payload["key"]), str(payload["value"]))
            else:
                self.memtable.delete(str(payload["key"]))
        return self

    def close(self) -> None:
        self.wal.close()

    def __enter__(self) -> "Store":
        return self.open()

    def __exit__(self, *_: object) -> None:
        self.close()

    # -- writes --------------------------------------------------------------
    def put(self, key: str, value: str) -> None:
        self._check_key(key)
        self.wal.append(PUT, key, value)
        self.memtable.put(key, value)
        self.writes += 1
        if self.memtable.is_full():
            self.flush()

    def delete(self, key: str) -> None:
        self._check_key(key)
        self.wal.append(DEL, key)
        self.memtable.delete(key)
        self.writes += 1
        if self.memtable.is_full():
            self.flush()

    def flush(self) -> str | None:
        """Seal the memtable into a new table. Returns the path, or None when nothing was live."""
        if not self.memtable.entries:
            return None
        items = self.memtable.items()
        path = self._table_path(self.next_table_number)
        table = SSTable.write(path, items)
        self.tables.insert(0, table)
        self.memtable.clear()
        self.wal.reset()
        self.wal_records = 0
        return path

    def compact(self) -> dict[str, object]:
        """Merge every table plus the memtable into one, dropping unreachable tombstones.

        Order matters: oldest table first, newest last, memtable last of all -- the incremental
        merge lets each newer layer overwrite the key's previous owner, so the surviving value is
        the newest, and the surviving rows stream straight into the new table: no full copy of the
        sealed payload is ever built. (Writing this the other way round kept the *oldest* value,
        which the compaction test caught.)
        """
        removed = [table.path for table in self.tables]
        path = self._table_path(self.next_table_number)
        writer = TableWriter(path)
        keys = 0
        try:
            for key, value in self._merged_rows():
                if value is None:
                    continue  # nothing older remains below this table: the tombstone is unreachable
                writer.add(key, value)
                keys += 1
            new_table = writer.finish()
        except BaseException:
            writer.abort()
            raise
        for old in removed:
            if os.path.exists(old):
                os.unlink(old)
        self.tables = [new_table]
        self.memtable.clear()
        self.wal.reset()
        self.wal_records = 0
        return {"table": path, "keys": keys, "removedTables": len(removed)}

    # -- reads ---------------------------------------------------------------
    def get(self, key: str) -> tuple[bool, str | None]:
        found, value = self.memtable.get(key)
        if found:
            return True, value
        for table in self.tables:
            found, value = table.get(key)
            if found:
                return True, value
        return False, None

    def scan(self, start: str | None = None, end: str | None = None, limit: int | None = None) -> list[tuple[str, str]]:
        if limit is not None and limit <= 0:
            raise ValidationError("limit must be > 0", value=limit)
        if start and end and end < start:
            raise ValidationError("end must be >= start", value=f"{start}..{end}")
        rows: list[tuple[str, str]] = []
        merged = self._merged_rows(start=start, end=end)
        try:
            for key, value in merged:
                if value is None:
                    continue  # tombstone hides whatever an older layer still holds for this key
                rows.append((key, value))
                if limit is not None and len(rows) >= limit:
                    break  # close() below stops every cursor; no later entry is touched
        finally:
            merged.close()  # releases the tables' read handles deterministically
        return rows

    def snapshot(self) -> Snapshot:
        return Snapshot(sequence=self.writes, visible=tuple(self.scan()))

    def _merged_rows(self, start: str | None = None, end: str | None = None) -> Iterator[tuple[str, str | None]]:
        """Incrementally merge the memtable and every sealed table in global key order.

        Layers are never copied: each layer contributes one forward cursor (a probe-only disk
        cursor for tables), and a heap hands back one distinct key at a time together with the
        value of its *newest* owner -- a tombstone marker surfaces as ``None``. Older copies of the
        same key are drained (and their value bytes never read) before the row is yielded.
        """
        cursors: list[_Cursor] = []
        try:
            memtable_cursor = _MemTableCursor(self.memtable.entries, start)
            if memtable_cursor.key is not None:
                cursors.append(memtable_cursor)
            for rank, table in enumerate(self.tables, start=1):  # tables are ordered newest first
                cursor = _TableCursor(table, rank, start)
                if cursor.key is None:
                    cursor.close()
                    continue
                cursors.append(cursor)
            heap = [(cursor.key, cursor.rank, cursor) for cursor in cursors]
            heapq.heapify(heap)
            while heap:
                key, _, winner = heap[0]
                if end is not None and key >= end:
                    return
                value = None if winner.tombstone else winner.read_value()
                while heap and heap[0][0] == key:  # retire every older copy of this key
                    _, _, cursor = heapq.heappop(heap)
                    cursor.advance()
                    if cursor.key is not None:
                        heapq.heappush(heap, (cursor.key, cursor.rank, cursor))
                yield key, value
        finally:
            for cursor in cursors:
                close = getattr(cursor, "close", None)
                if close is not None:
                    close()

    # -- reporting -----------------------------------------------------------
    @property
    def next_table_number(self) -> int:
        numbers = [int(TABLE_PATTERN.match(os.path.basename(path)).group(1)) for path in self._table_paths()]
        return (max(numbers) + 1) if numbers else 1

    def stats(self) -> StoreStats:
        tombstones = sum(1 for value in self.memtable.entries.values() if value is None)
        return StoreStats(
            directory=os.path.abspath(self.directory),
            tables=len(self.tables),
            sealed_entries=sum(table.count for table in self.tables),
            memtable_entries=len(self.memtable.entries),
            memtable_bytes=self.memtable.bytes_used,
            tombstones=tombstones,
            wal_records=self.wal_records,
            wal_truncated_bytes=self.wal_truncated_bytes,
            next_table_number=self.next_table_number,
        )

    def verify(self) -> dict[str, object]:
        """Re-open every artifact from disk and report what recovery had to repair."""
        tables = []
        for path in self._table_paths():
            table = SSTable.open(path)  # raises CorruptionError when the seal is broken
            tables.append(table.to_document())
        with WriteAheadLog(self.wal.path) as log:
            report = log.recover()
        state = replay(report.records)
        return {
            "tables": tables,
            "wal": {
                "records": len(report.records),
                "truncatedBytes": report.truncated_bytes,
                "lastSequence": report.last_sequence,
                "putKeys": sum(1 for value in state.values() if value is not None),
                "deletedKeys": sum(1 for value in state.values() if value is None),
            },
        }

    # -- internals -----------------------------------------------------------
    def _table_paths(self) -> list[str]:
        if not os.path.isdir(self.directory):
            return []
        paths = [os.path.join(self.directory, name) for name in os.listdir(self.directory) if TABLE_PATTERN.match(name)]
        return sorted(paths, key=lambda path: int(TABLE_PATTERN.match(os.path.basename(path)).group(1)))

    def _table_path(self, number: int) -> str:
        return os.path.join(self.directory, f"table-{number:06d}.sst")

    @staticmethod
    def _check_key(key: str) -> None:
        if not key:
            raise ValidationError("key must be non-empty", value=key)
        if any(character in key for character in "\t\n"):
            raise ValidationError("key must not contain tabs or newlines", value=key)

"""Sorted table on disk: one header, one line per key in ascending order, one footer.

Layout (UTF-8, LF):

    header  {"count":N,"bloomBits":M,"bloomHashes":K}
    entry   <key><TAB><base64 value>      (a tombstone stores the marker `~`)
    footer  {"bloom":"<base64 bits>","crc32":"<8 hex of all preceding bytes>"}

Opening a table never materialises its payload: the file is streamed once, verifying the crc32
seal and every structural rule, but only the bloom filter, the entry count and a compact array of
entry byte offsets survive in memory. Values stay on disk and are fetched on demand; resident
memory is O(N * word) plus the bloom bits, independent of the total value byte count.

Lookups exploit the sorted keys: the bloom filter settles an absent key without touching the
entry region at all; a possible hit binary-searches entries with probes that read through the
candidate key and exactly one value-marker byte, so the bytes read never grow with value length.
Only an exact match pays for a full value read. Range scans stream rows in key order through
``open_stream`` / ``scan_rows``.
"""

from __future__ import annotations

import base64
import binascii
import codecs
import hashlib
import json
import os
import zlib
from array import array
from dataclasses import dataclass
from typing import Iterator

from .errors import CorruptionError, ValidationError

TOMBSTONE = "~"
TOMBSTONE_BYTE = ord(TOMBSTONE)
# A value encoded as the empty base64 string (the empty string itself: `key\t\n`) has no marker
# byte at all; zero never occurs in the base64 alphabet, so it doubles as the "empty" marker.
EMPTY_MARKER = 0
BLOOM_HASHES = 4
# Fixed block size for the open-time structural pass. It bounds the decode buffer to a constant
# regardless of how large the payload on disk is: residency never grows with the value byte count.
VALIDATE_BLOCK = 1 << 20
# First read of a locating probe: keys are normally short, so a small chunk usually reaches the
# tab and the value marker; a key longer than this keeps reading in the continuation size.
PROBE_INITIAL = 64
PROBE_BLOCK = 1 << 12
_TMP_ENTRY = ".tmp"
_TMP_FINAL = ".out"


def _hashes(key: str, count: int, bits: int) -> list[int]:
    digest = hashlib.sha256(key.encode("utf-8")).digest()
    return [int.from_bytes(digest[index * 4 : index * 4 + 4], "big") % bits for index in range(count)]


@dataclass(slots=True)
class BloomFilter:
    bits: int
    hashes: int
    payload: bytearray

    @classmethod
    def create(cls, expected_keys: int, bits_per_key: int = 10) -> "BloomFilter":
        bits = max(64, bits_per_key * max(1, expected_keys))
        return cls(bits=bits, hashes=BLOOM_HASHES, payload=bytearray((bits + 7) // 8))

    @classmethod
    def build(cls, keys: list[str], bits_per_key: int = 10) -> "BloomFilter":
        bloom = cls.create(len(keys), bits_per_key)
        for key in keys:
            bloom.add(key)
        return bloom

    @classmethod
    def loads(cls, bits: int, hashes: int, encoded: str) -> "BloomFilter":
        return cls(bits=bits, hashes=hashes, payload=bytearray(base64.b64decode(encoded)))

    def add(self, key: str) -> None:
        for position in _hashes(key, self.hashes, self.bits):
            self.payload[position // 8] |= 1 << (position % 8)

    def dumps(self) -> str:
        return base64.b64encode(bytes(self.payload)).decode("ascii")

    def might_contain(self, key: str) -> bool:
        return all(self.payload[position // 8] & (1 << (position % 8)) for position in _hashes(key, self.hashes, self.bits))

    def to_document(self) -> dict[str, int]:
        return {"bits": self.bits, "hashes": self.hashes, "bytes": len(self.payload)}


def _decode_value(encoded: str, *, path: str, line: int) -> str | None:
    """Decode one entry payload; the tombstone marker is None, anything else must be base64 UTF-8."""
    if encoded == TOMBSTONE:
        return None
    try:
        raw = base64.b64decode(encoded, validate=True)
    except (ValueError, binascii.Error) as error:
        raise CorruptionError("entry value must be base64", path=path, line=line) from error
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as error:
        raise CorruptionError("entry value must decode to UTF-8", path=path, line=line) from error


class TableWriter:
    """Sink for a sorted row stream.

    Entry lines spool to a temp file while the running crc32 accumulates and the bloom filter is
    built incrementally, so callers (notably compaction) never hold an entire table -- or a merged
    copy of their input tables -- in memory. The header only exists once the count is known, so
    the final file is assembled in a second streaming pass and atomically renamed into place.
    """

    __slots__ = ("path", "entry_tmp", "final_tmp", "bits_per_key", "handle", "crc", "count", "previous")

    def __init__(self, path: str, *, bits_per_key: int = 10) -> None:
        self.path = path
        self.entry_tmp = path + _TMP_ENTRY
        self.final_tmp = path + _TMP_FINAL
        self.bits_per_key = bits_per_key
        self.handle = open(self.entry_tmp, "wb")
        self.crc = 0
        self.count = 0
        self.previous: str | None = None

    def add(self, key: str, value: str | None) -> None:
        if self.previous is not None and key <= self.previous:
            if key == self.previous:
                raise ValidationError("sstable keys must be unique", key=key)
            raise ValidationError("sstable entries must be written in ascending key order", key=key)
        encoded = TOMBSTONE if value is None else base64.b64encode(value.encode("utf-8")).decode("ascii")
        block = f"{key}\t{encoded}\n".encode("utf-8")
        self.handle.write(block)
        self.crc = zlib.crc32(block, self.crc)
        self.previous = key
        self.count += 1

    def finish(self) -> "SSTable":
        self.handle.flush()
        os.fsync(self.handle.fileno())
        self.handle.close()
        # The count is only known once every row arrived, so size the bloom filter now and build
        # it while the spool is re-read for assembly: one entry line is resident at a time.
        bloom = BloomFilter.create(self.count, self.bits_per_key)
        header = json.dumps(
            {"count": self.count, "bloomBits": bloom.bits, "bloomHashes": bloom.hashes},
            separators=(",", ":"),
        ) + "\n"
        header_bytes = header.encode("utf-8")
        checksum = zlib.crc32(header_bytes)
        rows = 0
        with open(self.entry_tmp, "rb") as source, open(self.final_tmp, "wb") as target:
            target.write(header_bytes)
            while True:
                line = source.readline()
                if not line:
                    break
                rows += 1
                tab = line.find(b"\t")
                try:
                    bloom.add(line[:tab].decode("utf-8"))
                except UnicodeDecodeError as error:
                    raise CorruptionError("entry key must be UTF-8", path=self.path, line=rows + 1) from error
                checksum = zlib.crc32(line, checksum)
                target.write(line)
            footer = json.dumps(
                {"bloom": bloom.dumps(), "crc32": format(checksum & 0xFFFFFFFF, "08x")},
                separators=(",", ":"),
            )
            target.write(footer.encode("utf-8"))
            target.write(b"\n")
            target.flush()
            os.fsync(target.fileno())
        os.replace(self.final_tmp, self.path)
        os.unlink(self.entry_tmp)
        return SSTable.open(self.path)

    def abort(self) -> None:
        try:
            self.handle.close()
        except Exception:
            pass
        for tmp in (self.entry_tmp, self.final_tmp):
            if os.path.exists(tmp):
                os.unlink(tmp)


@dataclass(slots=True)
class SSTable:
    path: str
    bloom: BloomFilter
    count: int
    # Byte offset of the start of every entry line, in key order. Eight bytes per entry regardless
    # of pointer width; this array is the table's only per-key resident structure.
    offsets: array

    @classmethod
    def write(cls, path: str, items: list[tuple[str, str | None]], *, bits_per_key: int = 10) -> "SSTable":
        keys = [key for key, _ in items]
        if keys != sorted(keys):
            raise ValidationError("sstable entries must be written in ascending key order")
        if len(set(keys)) != len(keys):
            raise ValidationError("sstable keys must be unique")
        writer = TableWriter(path, bits_per_key=bits_per_key)
        try:
            for key, value in items:
                writer.add(key, value)
            return writer.finish()
        except BaseException:
            writer.abort()
            raise

    @classmethod
    def open(cls, path: str) -> "SSTable":
        size = os.path.getsize(path)
        if size < 2:
            raise CorruptionError("table is too short to hold a footer", path=path)
        with open(path, "rb") as handle:
            handle.seek(size - 1)
            if handle.read(1) != b"\n":
                raise CorruptionError("table is not newline terminated", path=path)
            # The footer is one short JSON line; read only the tail that can contain it.
            chunk_start = max(0, size - 65536)
            handle.seek(chunk_start)
            tail = handle.read(size - chunk_start)
        rel = tail.rfind(b"\n", 0, len(tail) - 1)
        if rel < 0:
            raise CorruptionError("table is too short to hold a footer", path=path)
        footer_start = chunk_start + rel + 1
        prefix_len = footer_start
        try:
            footer = json.loads(tail[rel + 1 : -1].decode("utf-8").strip())
        except (json.JSONDecodeError, UnicodeDecodeError) as error:
            raise CorruptionError("unreadable footer", path=path) from error
        if not isinstance(footer, dict) or not isinstance(footer.get("crc32"), str) or not isinstance(footer.get("bloom"), str):
            raise CorruptionError("footer is missing crc32 or bloom", path=path)

        offsets: array = array("Q")
        checksum = 0
        seen = 0
        previous: str | None = None
        alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        try:
            with open(path, "rb") as handle:
                header_line = handle.readline()
                if not header_line or not header_line.endswith(b"\n") or handle.tell() > prefix_len:
                    raise CorruptionError("missing or overlong header", path=path)
                checksum = zlib.crc32(header_line)
                try:
                    header = json.loads(header_line[:-1].decode("utf-8"))
                except (json.JSONDecodeError, UnicodeDecodeError) as error:
                    raise CorruptionError("unreadable header", path=path) from error
                if not isinstance(header, dict):
                    raise CorruptionError("header must be an object", path=path)
                try:
                    bloom_bits = int(header["bloomBits"])  # type: ignore[arg-type]
                    bloom_hashes = int(header["bloomHashes"])  # type: ignore[arg-type]
                    expected_count = int(header["count"])  # type: ignore[arg-type]
                except (KeyError, TypeError, ValueError) as error:
                    raise CorruptionError("header field is missing or not an integer", path=path) from error
                if bloom_bits <= 0 or bloom_hashes <= 0 or expected_count < 0:
                    raise CorruptionError("header fields must be positive", path=path)

                # Stream the entry region in fixed blocks. The seal is updated per block, the
                # strict ordering is checked, and payloads are validated as base64-then-UTF-8 a
                # few decoded bytes at a time: the bytes of one value are never resident.
                buf = b""

                def pull() -> bytes:
                    nonlocal checksum
                    remaining = prefix_len - handle.tell()
                    if remaining <= 0:
                        return b""
                    chunk = handle.read(min(VALIDATE_BLOCK, remaining))
                    checksum = zlib.crc32(chunk, checksum)
                    return chunk

                while handle.tell() - len(buf) < prefix_len:
                    offsets.append(handle.tell() - len(buf))
                    # -- key up to the tab ----------------------------------------------
                    while b"\t" not in buf:
                        if b"\n" in buf:
                            raise CorruptionError("entry without a separator", path=path, line=seen + 1)
                        chunk = pull()
                        if not chunk:
                            raise CorruptionError("entry line is unterminated", path=path, line=seen + 1)
                        buf += chunk
                    tab_index = buf.find(b"\t")
                    if b"\n" in buf[:tab_index]:
                        raise CorruptionError("entry without a separator", path=path, line=seen + 1)
                    try:
                        key = bytes(buf[:tab_index]).decode("utf-8")
                    except UnicodeDecodeError as error:
                        raise CorruptionError("entry key must be UTF-8", path=path, line=seen + 1) from error
                    if not key:
                        raise CorruptionError("entry has an empty key", path=path, line=seen + 1)
                    if previous is not None and key <= previous:
                        raise CorruptionError(
                            "entries must be strictly ascending and unique",
                            path=path,
                            line=seen + 1,
                            key=key,
                        )
                    buf = buf[tab_index + 1 :]
                    if not buf:
                        chunk = pull()
                        if not chunk:
                            raise CorruptionError("entry line is unterminated", path=path, line=seen + 1)
                        buf = chunk

                    # -- the payload: empty, tombstone, or base64 value ------------------
                    if buf[:1] == b"\n":
                        buf = buf[1:]  # empty string value
                    elif buf[:1] == b"~":
                        if len(buf) >= 2:
                            if buf[1] != 0x0A:
                                raise CorruptionError("invalid tombstone payload", path=path, line=seen + 1)
                            buf = buf[2:]
                        else:
                            chunk = pull()
                            if not chunk or chunk[0] != 0x0A:
                                raise CorruptionError("invalid tombstone payload", path=path, line=seen + 1)
                            buf = chunk[1:]
                    else:
                        pending = b""
                        decoder = codecs.getincrementaldecoder("utf-8")(errors="strict")

                        def feed(piece: bytes, *, final: bool) -> None:
                            """Validate base64 incrementally: between chunks keep at least the
                            last quad pending (the only quad that may carry padding), decode the
                            aligned prefix, and stream raw bytes through a UTF-8 decoder."""
                            nonlocal pending
                            data = pending + piece
                            if final:
                                groups, pending = data, b""
                                core = groups.rstrip(b"=")
                                pad_count = len(groups) - len(core)
                                if core.strip(alphabet) or pad_count > 2 or len(groups) % 4:
                                    raise CorruptionError("entry value must be base64", path=path, line=seen + 1)
                            else:
                                if len(data) < 4:
                                    pending = data
                                    return
                                # Reserve the trailing quad: padding ('=' / '==') can only occur
                                # in the very last quad, which the newline-bearing chunk finalises.
                                end = (len(data) - 4) & ~3
                                groups, pending = data[:end], data[end:]
                                if groups.strip(alphabet):
                                    raise CorruptionError("entry value must be base64", path=path, line=seen + 1)
                            if groups:
                                try:
                                    raw = base64.b64decode(groups, validate=True)
                                    decoder.decode(raw)
                                    if final:
                                        decoder.decode(b"", final=True)
                                except (binascii.Error, UnicodeDecodeError, ValueError) as error:
                                    raise CorruptionError("entry value must be base64 UTF-8", path=path, line=seen + 1) from error

                        while True:
                            newline = buf.find(b"\n")
                            if newline >= 0:
                                feed(buf[:newline], final=True)
                                buf = buf[newline + 1 :]
                                break
                            feed(buf, final=False)
                            buf = b""
                            chunk = pull()
                            if not chunk:
                                raise CorruptionError("entry line is unterminated", path=path, line=seen + 1)
                            buf = chunk
                    previous = key
                    seen += 1

            if seen != expected_count:
                raise CorruptionError(
                    "entry count differs from the header",
                    path=path,
                    expected=expected_count,
                    found=seen,
                )
            if format(checksum & 0xFFFFFFFF, "08x") != footer["crc32"]:
                raise CorruptionError("table checksum mismatch", path=path)
            try:
                bloom = BloomFilter.loads(bloom_bits, bloom_hashes, str(footer["bloom"]))
            except (binascii.Error, ValueError) as error:
                raise CorruptionError("bloom payload must be base64", path=path) from error
            if len(bloom.payload) != (bloom_bits + 7) // 8:
                raise CorruptionError("bloom payload length does not match bloomBits", path=path)
        except CorruptionError:
            raise
        except (OSError, UnicodeDecodeError, ValueError) as error:
            raise CorruptionError("table could not be parsed", path=path) from error
        return cls(path=path, bloom=bloom, count=seen, offsets=offsets)

    # -- internals -----------------------------------------------------------
    def _slot_at_or_after(self, handle: object, key: str | None) -> int:
        """First slot whose entry key is >= ``key`` (0 when ``key`` is None)."""
        if key is None:
            return 0
        lo, hi = 0, len(self.offsets)
        while lo < hi:
            mid = (lo + hi) // 2
            candidate, _ = self._probe(handle, mid)
            if candidate < key:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def _probe(self, handle: object, slot: int) -> tuple[str, int]:
        """Read just enough to locate an entry: its key and one value-marker byte.

        Returns ``(key, marker)``: ``~`` means tombstone, :data:`EMPTY_MARKER` means the empty
        string, and anything else (a base64 alphabet byte) says "a value exists". The value bytes
        are never part of this read.
        """
        handle.seek(int(self.offsets[slot]))
        key_bytes = b""
        size = PROBE_INITIAL
        while True:
            block = handle.read(size)
            if not block:
                raise CorruptionError("entry line is unterminated", path=self.path, line=slot + 2)
            tab = block.find(b"\t")
            newline = block.find(b"\n")
            if tab >= 0 and (newline < 0 or tab < newline):
                key_bytes += block[:tab]
                marker = block[tab + 1 : tab + 2]
                if not marker:
                    marker = handle.read(1)
                if not marker:
                    raise CorruptionError("entry without a value", path=self.path, line=slot + 2)
                code = marker[0]
                if code == 0x0A:
                    code = EMPTY_MARKER
                break
            if newline >= 0:
                raise CorruptionError("entry without a separator", path=self.path, line=slot + 2)
            key_bytes += block
            size = PROBE_BLOCK  # long key: keep reading in modest chunks, never whole values
        try:
            return key_bytes.decode("utf-8"), code
        except UnicodeDecodeError as error:
            raise CorruptionError("entry key must be UTF-8", path=self.path, line=slot + 2) from error

    def _read_full(self, handle: object, slot: int) -> tuple[str, str | None]:
        handle.seek(int(self.offsets[slot]))
        line = handle.readline()
        if not line.endswith(b"\n"):
            raise CorruptionError("entry line is unterminated", path=self.path, line=slot + 2)
        entry = line[:-1]
        tab = entry.find(b"\t")
        if tab <= 0:
            raise CorruptionError("entry without a separator", path=self.path, line=slot + 2)
        try:
            key = entry[:tab].decode("utf-8")
            encoded = entry[tab + 1 :].decode("ascii")
        except UnicodeDecodeError as error:
            raise CorruptionError("entry must be UTF-8 key with ASCII base64 value", path=self.path, line=slot + 2) from error
        return key, _decode_value(encoded, path=self.path, line=slot + 2)

    # -- reads ---------------------------------------------------------------
    def get(self, key: str) -> tuple[bool, str | None]:
        if not self.bloom.might_contain(key):
            return False, None
        with open(self.path, "rb") as handle:
            lo, hi = 0, len(self.offsets)
            while lo < hi:
                mid = (lo + hi) // 2
                candidate, marker = self._probe(handle, mid)
                if candidate < key:
                    lo = mid + 1
                elif candidate > key:
                    hi = mid
                elif marker == TOMBSTONE_BYTE:
                    return True, None
                elif marker == EMPTY_MARKER:
                    return True, ""
                else:
                    _, value = self._read_full(handle, mid)
                    return True, value
        return False, None

    def open_stream(self, start: str | None = None) -> "RowStream":
        return RowStream(self, start)

    def scan_rows(self, start: str | None = None, end: str | None = None) -> Iterator[tuple[str, str | None]]:
        """Yield rows with ``start <= key < end`` (either bound optional), one line at a time."""
        stream = self.open_stream(start)
        try:
            while stream.head is not None:
                key, marker = stream.head
                if end is not None and key >= end:
                    return
                if marker == TOMBSTONE_BYTE:
                    value = None
                elif marker == EMPTY_MARKER:
                    value = ""
                else:
                    value = stream.value()
                yield key, value
                stream.advance()
        finally:
            stream.close()

    def items(self) -> list[tuple[str, str | None]]:
        return list(self.scan_rows())

    def to_document(self) -> dict[str, object]:
        return {"path": self.path, "keys": self.count, "bloom": self.bloom.to_document()}


class RowStream:
    """Forward cursor over a table.

    The head holds only ``(key, marker)``: the value bytes of a row are fetched on demand via
    :meth:`value`, so a k-way merge never reads values that a newer layer shadows (or that are
    tombstones). ``close`` releases the file handle.
    """

    __slots__ = ("table", "handle", "slot", "head")

    def __init__(self, table: SSTable, start: str | None = None) -> None:
        self.table = table
        self.handle = open(table.path, "rb")
        self.slot = table._slot_at_or_after(self.handle, start)
        self.head: tuple[str, int] | None = None
        self._load()

    def _load(self) -> None:
        if self.slot < len(self.table.offsets):
            self.head = self.table._probe(self.handle, self.slot)
            self.slot += 1
        else:
            self.head = None

    def value(self) -> str:
        """Full value of the current row; valid only when the marker is not a tombstone."""
        _, value = self.table._read_full(self.handle, self.slot - 1)
        return value  # type: ignore[return-value]

    def advance(self) -> None:
        self._load()

    def close(self) -> None:
        self.handle.close()
        self.head = None

"""Write-ahead log: append-only, one checksummed record per line, crash-safe recovery.

Line format (a single space separates the checksum from the payload):

    <crc32 of the canonical payload, 8 lowercase hex><space><canonical JSON payload>

The payload is `{"op":"put"|"del","key":...,"seq":N,"value":...}` with `value` omitted for `del`.
Recovery reads forward, verifies every checksum, and stops at the first record that is missing,
truncated or corrupt -- that is exactly the shape a crash leaves behind. The store then truncates
the file to the last good offset so the next append starts from a consistent place.
"""

from __future__ import annotations

import json
import os
import zlib
from dataclasses import dataclass
from typing import Iterable, Iterator

from .errors import ParseError, ValidationError

PUT = "put"
DEL = "del"
OPS = (PUT, DEL)


def canonical(payload: dict[str, object]) -> str:
    return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def encode_record(payload: dict[str, object]) -> str:
    body = canonical(payload)
    checksum = format(zlib.crc32(body.encode("utf-8")) & 0xFFFFFFFF, "08x")
    return f"{checksum} {body}\n"


def decode_record(line: str, *, line_number: int | None = None) -> dict[str, object]:
    stripped = line.rstrip("\n")
    if not stripped:
        raise ParseError("empty record", line=line_number)
    checksum, _, body = stripped.partition(" ")
    if len(checksum) != 8 or not body:
        raise ParseError("record must be '<8 hex><space><json>'", line=line_number)
    expected = format(zlib.crc32(body.encode("utf-8")) & 0xFFFFFFFF, "08x")
    if checksum != expected:
        raise ParseError("record checksum mismatch", line=line_number)
    try:
        payload = json.loads(body)
    except json.JSONDecodeError as error:
        raise ParseError(f"invalid record JSON: {error.msg}", line=line_number) from error
    if not isinstance(payload, dict):
        raise ParseError("record payload must be an object", line=line_number)
    if payload.get("op") not in OPS:
        raise ParseError(f"op must be one of {', '.join(OPS)}", line=line_number)
    key = payload.get("key")
    if not isinstance(key, str) or not key:
        raise ParseError("key must be a non-empty string", line=line_number)
    sequence = payload.get("seq")
    if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:
        raise ParseError("seq must be a positive integer", line=line_number)
    if payload["op"] == PUT and not isinstance(payload.get("value"), str):
        raise ParseError("put requires a string value", line=line_number)
    return payload


@dataclass(slots=True)
class RecoveryReport:
    records: list[dict[str, object]]
    truncated_bytes: int
    last_sequence: int
    good_bytes: int


class WriteAheadLog:
    """Append records; recover them after a crash; truncate a torn tail."""

    def __init__(self, path: str, *, sync: bool = True) -> None:
        self.path = path
        self.sync = sync
        self._handle = None
        self._sequence = 0

    # -- lifecycle -----------------------------------------------------------
    def open(self) -> None:
        if self._handle is not None:  # reopening must not leak the previous handle
            self.close()
        directory = os.path.dirname(os.path.abspath(self.path)) or "."
        os.makedirs(directory, exist_ok=True)
        self._handle = open(self.path, "a+", encoding="utf-8", newline="\n")
        self._handle.seek(0, os.SEEK_END)

    def close(self) -> None:
        if self._handle is not None:
            self._handle.flush()
            if self.sync:
                os.fsync(self._handle.fileno())
            self._handle.close()
            self._handle = None

    def __enter__(self) -> "WriteAheadLog":
        self.open()
        return self

    def __exit__(self, *_: object) -> None:
        self.close()

    # -- writing -------------------------------------------------------------
    @property
    def last_sequence(self) -> int:
        return self._sequence

    def append(self, op: str, key: str, value: str | None = None) -> int:
        if op not in OPS:
            raise ValidationError(f"op must be one of {', '.join(OPS)}", value=op)
        if not key:
            raise ValidationError("key must be non-empty", value=key)
        if op == PUT and value is None:
            raise ValidationError("put requires a value", value=key)
        if self._handle is None:
            raise ValidationError("log is not open")
        self._sequence += 1
        payload: dict[str, object] = {"op": op, "key": key, "seq": self._sequence}
        if op == PUT:
            payload["value"] = value
        self._handle.write(encode_record(payload))
        self._handle.flush()
        if self.sync:
            os.fsync(self._handle.fileno())
        return self._sequence

    def reset(self) -> None:
        """Used by `Store.flush`: the log only ever describes what is not yet sealed."""
        if self._handle is not None:
            self._handle.close()
            self._handle = None
        with open(self.path, "w", encoding="utf-8", newline="\n"):
            pass
        self._sequence = 0
        self.open()

    # -- reading -------------------------------------------------------------
    def recover(self) -> RecoveryReport:
        """Read what is intact; report how many bytes of torn tail were dropped."""
        records: list[dict[str, object]] = []
        good_bytes = 0
        last_sequence = 0
        if not os.path.exists(self.path):
            return RecoveryReport([], 0, 0, 0)
        with open(self.path, "rb") as handle:
            raw = handle.read()
        for number, line in enumerate(raw.splitlines(keepends=True), start=1):
            try:
                payload = decode_record(line.decode("utf-8"), line_number=number)
            except (ParseError, UnicodeDecodeError):
                break
            records.append(payload)
            good_bytes += len(line)
            last_sequence = int(payload["seq"])  # type: ignore[arg-type]
        truncated = len(raw) - good_bytes
        if truncated:
            with open(self.path, "r+b") as handle:
                handle.truncate(good_bytes)
                handle.flush()
                os.fsync(handle.fileno())
        self._sequence = last_sequence
        return RecoveryReport(records, truncated, last_sequence, good_bytes)

    def records(self) -> Iterator[dict[str, object]]:
        yield from self.recover().records


def replay(records: Iterable[dict[str, object]]) -> dict[str, str | None]:
    """Fold WAL records into the state they describe (None marks a deleted key)."""
    state: dict[str, str | None] = {}
    for payload in records:
        if payload["op"] == PUT:
            state[str(payload["key"])] = str(payload["value"])
        else:
            state[str(payload["key"])] = None
    return state

"""In-memory table: the newest writes, held until they are sealed into a sorted table.

`None` is a tombstone, not an absent key -- the distinction is what lets compaction drop deletes
only once every older copy has been merged away.
"""

from __future__ import annotations

from dataclasses import dataclass, field


@dataclass(slots=True)
class MemTable:
    limit_bytes: int = 1 << 20
    entries: dict[str, str | None] = field(default_factory=dict)
    bytes_used: int = field(default=0, init=False)

    def put(self, key: str, value: str) -> None:
        self._store(key, value)

    def delete(self, key: str) -> None:
        self._store(key, None)

    def get(self, key: str) -> tuple[bool, str | None]:
        """Return `(found, value)`; a tombstone is found with value None."""
        if key in self.entries:
            return True, self.entries[key]
        return False, None

    def items(self) -> list[tuple[str, str | None]]:
        return sorted(self.entries.items())

    def is_full(self) -> bool:
        return self.bytes_used >= self.limit_bytes

    def clear(self) -> None:
        self.entries.clear()
        self.bytes_used = 0

    def _store(self, key: str, value: str | None) -> None:
        previous = self.entries.get(key)
        if previous is not None:
            self.bytes_used -= len(key) + len(previous)
        elif key in self.entries:
            self.bytes_used -= len(key)
        self.entries[key] = value
        self.bytes_used += len(key) + (len(value) if value is not None else 0)

"""Exception hierarchy with stable `kind` values.

`CorruptionError` is separate from `ParseError` on purpose: a torn WAL tail is expected after a
crash and is repaired, while a corrupt *sealed* table is not recoverable and must stop the caller.
"""

from __future__ import annotations


class KVError(Exception):
    """Base class for every error this package raises on purpose."""

    kind = "kv_error"

    def __init__(self, message: str, **context: object) -> None:
        super().__init__(message)
        self.message = message
        self.context = {key: value for key, value in context.items() if value is not None}

    def to_document(self) -> dict[str, object]:
        document: dict[str, object] = {"error": self.kind, "message": self.message}
        document.update(self.context)
        return document


class ParseError(KVError):
    """Malformed input handed to the CLI or to a record decoder."""

    kind = "parse_error"

    def __init__(self, message: str, *, line: int | None = None, **context: object) -> None:
        super().__init__(message, line=line, **context)


class ValidationError(KVError):
    """A request that is well-formed but not allowed: bad key, bad range, bad limit."""

    kind = "validation_error"


class CorruptionError(KVError):
    """A sealed artifact failed its checksum; recovery is not safe to continue."""

    kind = "corruption_error"


class OutputError(KVError):
    """A path or write that cannot be completed without risking existing data."""

    kind = "output_error"

